-- Guia "Porto em 3 dias: Livraria Lello com ingresso marcado, Ribeira e metrô do aeroporto" (rascunho). Gerado por tools/gerar-migration-guia.ts a partir de content/guias/porto-em-3-dias.json.
-- Entra como rascunho: publique pelo painel (/admin-blog.html) depois de conferir a pré-visualização.
INSERT INTO blog_posts (id, slug, status, region_id, title, title_highlight, summary, lede, destination, cta_title, cover_url, cover_url_small, cover_alt, featured, body, reading_minutes)
VALUES ('2fcf7062-685d-4df8-84dc-fa0a3544183f', 'porto-em-3-dias', 'draft', 'portugal', 'Porto em 3 dias: Livraria Lello com ingresso marcado, Ribeira e metrô do aeroporto', 'Livraria Lello com ingresso marcado', 'Roteiro do Porto em 3 dias com Livraria Lello, Ribeira, Gaia, Jardim do Morro e Foz do Douro, o metrô do aeroporto, a francesinha, valores em euros e em reais e o guia em PDF para baixar de graça.', 'A Livraria Lello só recebe com ingresso de data e horário marcados: escolha o seu antes de viajar. O roteiro, os valores e o guia completo vão no celular.', 'Porto', NULL, '/assets/blog/porto-3-dias.jpg', '/assets/blog/porto-3-dias-m.jpg', 'Ponte Dom Luís I, no Porto, com um metrô de superfície cruzando o tabuleiro superior e a cidade ao fundo', 0, '[{"t":"pdf","href":"/guias/porto-em-3-dias.pdf","note":"PDF de 16 páginas, feito para ler no celular. Grátis, sem cadastro."},{"t":"p","text":"Livraria Lello, Ribeira, Gaia e Jardim do Morro, metrô do aeroporto e francesinha, com horários, valores em euro e em reais e checklist."},{"t":"tip","items":["Compre o ingresso da Lello e confirme o horário.","Veja a seção Documentos e antes de ir."],"title":"Como usar este roteiro"},{"t":"whatsapp"},{"t":"afiliado"},{"t":"h","text":"Centro histórico","label":"Dia 1"},{"t":"p","text":"Clérigos, São Bento, Sé e a Livraria Lello, a pé, com almoço de francesinha."},{"t":"img","src":"/assets/blog/porto-lello.jpg","alt":"Vitral do teto e escadaria vermelha da Livraria Lello, no Porto","caption":"Vitral do teto e escadaria vermelha da Livraria Lello.","credit":"Foto: Aaron Porras / Pexels","w":1000,"h":666},{"t":"ul","items":["**Manhã, Torre dos Clérigos:** Abre das 9h às 19h todos os dias. Torre e Museu: € 10 (cerca de R$ 62).","**Meio da manhã, Estação de São Bento:** Cerca de vinte mil azulejos de Jorge Colaço no átrio. Aberta das 6h30 à 1h. Sem preço no Visit Porto.","**Fim da manhã, Sé do Porto:** Catedral com claustro gótico. Visit Porto: € 4 (R$ 25). Horário diverge: confirmar.","**Hora do almoço, Livraria Lello:** € 15,95 (cerca de R$ 98), com data e horário marcados, dedutível num livro. Veja a seção Lello.","**Depois, Almoço de francesinha:** Prato típico do Porto. Veja a seção Onde comer."]},{"t":"tip","items":["O ingresso vale para uma data e um horário. O site da livraria indica menos movimento na hora do almoço e no fim da tarde. Veja a seção Lello."],"title":"Lello: horário marcado e menos movimento"},{"t":"tip","items":["Principal: Livraria Lello, com ingresso de data e horário","Grátis: Átrio da Estação de São Bento (confirmar)","Opcional: Torre dos Clérigos e claustro da Sé, com ingresso","**Nas atrações:** cerca de 5 horas","**A pé:** trajeto curto entre as paradas, com subidas e descidas","**Esforço:** moderado: calçada de pedra e ladeiras","Estimativas da Rota Certa, não dados oficiais. Não contam filas nem refeições.","**Dica da Rota Certa:** use tênis. A calçada de pedra do Porto escorrega quando molha."],"title":"Para planejar o Dia 1"},{"t":"p","text":"[Abrir a rota do Dia 1 no Google Maps](https://www.google.com/maps/dir/?api=1&origin=Torre%20dos%20Cl%C3%A9rigos%2C%20Porto&waypoints=Esta%C3%A7%C3%A3o%20de%20S%C3%A3o%20Bento%2C%20Porto%7CS%C3%A9%20do%20Porto&destination=Livraria%20Lello%2C%20Porto&travelmode=walking)"},{"t":"passeio","busca":"Porto centro histórico passeio a pé","title":"Passeios no centro do Porto"},{"t":"h","text":"Ribeira e Gaia","label":"Dia 2"},{"t":"p","text":"Palácio da Bolsa, a beira do Douro, a Ponte Dom Luís e o pôr do sol no Jardim do Morro."},{"t":"img","src":"/assets/blog/porto-ponte.jpg","alt":"Ponte Dom Luís I ao entardecer, vista da Ribeira, com Gaia e o Mosteiro da Serra do Pilar ao fundo","caption":"Ponte Dom Luís I ao entardecer.","credit":"Foto: Artūras Kokorevas / Pexels","w":1000,"h":666},{"t":"ul","items":["**Manhã, Palácio da Bolsa:** Visita guiada obrigatória, de cerca de 30 minutos. Das 9h às 18h30. € 14 (cerca de R$ 86).","A visita sai em português, espanhol, francês ou inglês, conforme a ordem de chegada. Dias de fechamento: confirmar no site.","**Almoço, Ribeira:** Calcorreie as ruelas e a beira do rio. Os restaurantes do cais enchem: reserve ou almoce numa rua de trás.","**Começo da tarde, Ponte Dom Luís:** A ponte liga a Ribeira a Gaia, do outro lado do Douro. Atravesse para seguir o resto do dia na margem de lá.","**Tarde, Caves de vinho do Porto:** As caves ficam em Gaia. A Cálem, na Avenida Diogo Leite, 344, anuncia visita com prova e visita com prova e fado. Preço, duração e horário: confirmar no site da cave.","**Opcional, Passeio de barco das seis pontes:** A Douro Criativo vende o cruzeiro de 50 minutos por € 18 (cerca de R$ 111). Saídas a cada 30 minutos, das 11h às 16h de outubro a março, do cais da Rota do Douro, em Gaia. Cancelamento grátis até 72 horas antes.","**Fim da tarde, Jardim do Morro:** Em Gaia, junto à Ponte Dom Luís, com vista do Porto no pôr do sol."]},{"t":"tip","items":["O Visit Porto descreve a Ribeira como zona classificada Patrimônio Mundial e cartão postal da cidade."],"title":"Ribeira: Patrimônio Mundial"},{"t":"tip","items":["Principal: Palácio da Bolsa, visita guiada","Grátis: Ribeira, Ponte Dom Luís e Jardim do Morro","Opcional: Caves de vinho do Porto e passeio de barco","**Nas atrações:** cerca de 6 horas","**A pé:** descidas até o rio e subidas em Gaia","**Esforço:** moderado","Estimativas da Rota Certa, não dados oficiais.","**Dica da Rota Certa:** chegue uns 30 a 40 minutos antes do pôr do sol e consulte a hora no celular. O jardim lota."],"title":"Para planejar o Dia 2"},{"t":"p","text":"[Abrir a rota do Dia 2 no Google Maps](https://www.google.com/maps/dir/?api=1&origin=Pal%C3%A1cio%20da%20Bolsa%2C%20Porto&waypoints=Cais%20da%20Ribeira%2C%20Porto%7CPonte%20Lu%C3%ADs%20I%2C%20Porto&destination=Jardim%20do%20Morro%2C%20Vila%20Nova%20de%20Gaia&travelmode=walking)"},{"t":"passeio","busca":"Porto Gaia passeio de barco Douro","title":"Passeios de barco no Douro"},{"t":"h","text":"Foz do Douro","label":"Dia 3"},{"t":"p","text":"Elétrico pela margem do rio até a Foz, com a orla e o mar para fechar a viagem."},{"t":"img","src":"/assets/blog/porto-foz.jpg","alt":"Farol no molhe do rio Douro, no Porto, com ondas batendo","caption":"Farol no molhe do rio Douro.","credit":"Foto: Tiana / Pexels","w":1000,"h":666},{"t":"ul","items":["**Manhã, Elétrico 1, do Infante ao Passeio Alegre:** Segundo o Visit Porto, o elétrico corre pela margem do Douro, do centro histórico, perto do funicular dos Guindais, ao jardim do Passeio Alegre.","**Fim da manhã, Passeio Alegre e orla:** Jardim onde o Douro encontra o mar. Siga pela orla até o molhe. Fonte antiga: confirmar.","**Almoço, Perto da Foz:** Almoce ali ou volte ao centro de elétrico. Se ainda não provou a francesinha, este é o momento.","**Tarde, Livre ou bate-volta de trem:** A CP publica horário urbano Porto São Bento a Aveiro, em vigor desde 26/07/2026. Duração, preço e outras cidades, como Braga: confirmar no site da CP."]},{"t":"tip","items":["O Visit Porto cita o bilhete a bordo por € 2,50 em uma página e por € 3 em outra. A STCP dá horário de verão com saída às 9h no Infante. Confirme o horário de inverno e o preço na STCP."],"title":"Preço e horário do elétrico: confirmar"},{"t":"tip","items":["Principal: Elétrico 1 até o Passeio Alegre","Grátis: Orla da Foz e praia","Opcional: Dia de trem para Aveiro","**No elétrico:** tempo de viagem: confirmar com a STCP","**Na Foz:** cerca de 3 horas","**Esforço:** baixo: orla plana","Estimativas da Rota Certa, não dados oficiais.","**Dica da Rota Certa:** deixe este dia por último. Ele é o mais leve e combina com o voo de volta. Do hotel ao aeroporto, vá de metrô violeta."],"title":"Para planejar o Dia 3"},{"t":"p","text":"[Abrir a rota do Dia 3 no Google Maps](https://www.google.com/maps/dir/?api=1&origin=Infante%2C%20Porto&destination=Passeio%20Alegre%2C%20Porto&travelmode=transit)"},{"t":"passeio","busca":"Porto Foz do Douro passeio","title":"Passeios na Foz do Douro"},{"t":"h","text":"Livraria Lello: como visitar","label":"Atração principal"},{"t":"p","text":"O ingresso custa € 15,95 (cerca de R$ 98), mas o valor pode ser usado como desconto na compra de um livro."},{"t":"ul","items":["**Desconto num livro:** O valor é dedutível em livros das Edições Livraria Lello. Outras edições e lembranças não entram.","**Data e horário marcados:** Vale só no dia escolhido e é individual e intransferível. A livraria recomenda comprar antes, online, para garantir o acesso na data e no horário que você quer.","**Menos movimento:** O site indica menor afluência na hora do almoço e no fim da tarde. Não prometemos que comprar antes evite fila."]},{"t":"tip","items":["Não é reembolsável. Faltar à data e à hora implica perder o ingresso (o FAQ fala em tolerância de 60 minutos). O horário pode mudar uma vez, até 24 horas antes, pelo link do e-mail."],"title":"Regras do ingresso"},{"t":"ul","items":["**Na porta:** Rua das Carmelitas, 144. Das 9h às 19h (o cabeçalho do site diz 19h30: confirmar). Não entram malas e mochilas de viagem. Fecha em 25/12, 1/1, Páscoa, 1/5 e 24/6."]},{"t":"h","text":"Metrô, Andante e transporte","label":"Na prática"},{"t":"p","text":"Do aeroporto ao centro, o metrô violeta leva cerca de 27 minutos até a Trindade."},{"t":"ul","items":["**Do aeroporto à Trindade:** Linha E (violeta), sentido Estádio do Dragão. O horário oficial de 7/9/2026 dá 27 minutos, com tolerância de 2. Precisa de bilhete de 4 zonas (Z4): € 2,30 (cerca de R$ 14), mais o cartão Andante, € 0,60 (cerca de R$ 3,70).","**Como usar o Andante:** Valide sempre antes de embarcar, a até 10 minutos antes. Sem validar, a multa é de € 95 (cerca de R$ 586). O Z4 vale por 1h15 depois da primeira validação.","**Outras opções:** Ônibus 601 e 602 vão ao centro. O Visit Porto cita táxi de € 20 a 25 (R$ 123 a 154), mas esse FAQ tem preços defasados: confirmar.","**Elétrico e trem:** Os elétricos 1, 18 e 22 cobrem o centro e o rio. Preço a bordo: confirmar (€ 2,50 ou € 3 no Visit Porto). Trem da CP: horário no site."]},{"t":"tip","items":["Portugal usa 230 V e tomada de pinos redondos. O plugue brasileiro não encaixa: leve adaptador."],"title":"Tomada e voltagem"},{"t":"h","text":"Onde comer: francesinha","label":"Sabores"},{"t":"p","text":"A francesinha é o prato típico mais famoso do Porto."},{"t":"ul","items":["**O que é:** Sanduíche de carnes, com camadas de queijo derretido, bife e embutidos, servida com batatas fritas e molho. O Visit Portugal a chama de \"uma verdadeira instituição\" e a Câmara do Porto, de iguaria portuense.","**Como pedir:** Cada casa faz o seu molho, então o sabor muda de um lugar para outro. Pergunte se vem com batata frita e se o molho é picante.","**Para beber:** O vinho do Porto é a bebida da região. O Visit Porto sugere fechar o dia numa cave de Gaia. Beba com moderação."]},{"t":"tip","items":["Este guia não traz preço de refeição porque não achamos fonte oficial. Confira o cardápio na porta e no site do restaurante antes de sentar."],"title":"Preços de restaurante"},{"t":"tip","items":["**Dica da Rota Certa:** saia das ruas mais turísticas da Ribeira para almoçar. Costuma ser mais fácil achar mesa."]},{"t":"h","text":"Documentos e antes de ir","label":"Checklist"},{"t":"tip","items":["O Brasil consta na lista de países isentos de visto para até 90 dias em qualquer período de 180. O passaporte deve ter sido emitido nos últimos 10 anos e valer 3 meses depois da saída da área Schengen."],"title":"Passaporte, sem visto para turismo"},{"t":"ul","items":["**Na chegada: digitais e foto:** O EES (Sistema de Entrada e Saída) opera desde 10/4/2026. Na fronteira registra passaporte, digitais e foto. Não há cadastro prévio.","**ETIAS: ainda não vale:** Em 12/11/2026, a página oficial da UE diz que o ETIAS não está em operação e que a data será avisada meses antes. Confirmar antes de comprar a passagem.","**Dinheiro e seguro:** A fronteira pode pedir prova de meios para a estada: valor, confirmar na fonte oficial. Recomendamos seguro-viagem com cobertura médica."]},{"t":"tip","items":["Passaporte válido por 3 meses além da volta.","Hospedagem e passagem de volta.","Seguro viagem com cobertura médica.","Ingresso da Lello com data e horário.","Adaptador de tomada."],"title":"Checklist"},{"t":"h","text":"Orçamento","label":"Planejamento"},{"t":"p","text":"O preço da passagem não é o preço da viagem."},{"t":"p","text":"Por adulto, com fonte: Lello, Clérigos e Bolsa somam € 39,95 (cerca de R$ 247); com o barco, € 57,95 (R$ 358). Metrô do aeroporto com o Andante: € 2,90 (R$ 18). Refeições, caves e elétrico não entram. Reais pela cotação do Banco Central de 11/11/2026; no cartão entram o IOF e o câmbio do banco."},{"t":"pdf","href":"/guias/porto-em-3-dias.pdf","note":"Leve o roteiro, as rotas e o orçamento no celular. Grátis, sem cadastro."},{"t":"h","text":"Valores oficiais e fontes","label":"Transparência"},{"t":"p","text":"Conferido em 12/11/2026 nos sites abaixo. Reais pela cotação de venda do Banco Central de 11/11/2026 (último fechamento disponível): € 1 = R$ 6,1706. Itens marcados \"confirmar\" não têm fonte oficial atual. Preços e regras mudam: confira antes de ir."},{"t":"ul","items":["**Lello:** € 15,95 (R$ 98). **Clérigos:** € 10 (R$ 62). **Bolsa:** € 14 (R$ 86). **Cruzeiro 6 pontes:** € 18 (R$ 111). **Metrô Z4:** € 2,30 (R$ 14). **Cartão Andante:** € 0,60 (R$ 3,70). **Multa sem validar:** € 95 (R$ 586). **Sé:** € 4 (R$ 25), Visit Porto, confirmar. **Elétrico, caves, táxi, trem, meios de subsistência:** confirmar."]},{"t":"tip","items":["Lello: [ingresso](https://tickets.livrarialello.pt/pt/1578-tickets/9583-ticket-voucher-livraria-lello/info) e [FAQ](https://livrarialello.pt/faqs/)","Metrô: [tarifário](https://www.metrodoporto.pt/pages/287), [FAQ](https://en.metrodoporto.pt/pages/394) e [horários de 7/9/2026](https://www.metrodoporto.pt/metrodoporto/uploads/document/file/807/horarios_setembro_26.pdf)","Turismo: [Visit Porto FAQ](https://backoffice.visitporto.travel/pt-PT/faq), [Sé](https://visitporto.travel/pt-PT/poi/5cd04b4bf979e0000193909e) e [São Bento](https://visitporto.travel/pt-PT/poi/5cd04b4ef979e00001fe480a)","Jardim do Morro: [Câmara de Gaia](https://www.cm-gaia.pt/pt/noticias/jardim-do-morro-esta-iluminado-e-mais-seguro/) e [Time Out](https://www.timeout.pt/porto/pt/noticias/apos-polemica-autarquia-recua-e-jardim-do-morro-ja-nao-vai-ser-vedado-082126) (imprensa)","Palácio da Bolsa: [turismo](https://www.palaciodabolsa.com/turismo/). Clérigos: [bilheteria](https://www.torredosclerigos.pt/en/ticket-office/)","Barco: [Douro Criativo](https://reservas.dourocriativo.pt/en/cruzeiro/6-bridges-cruise). Cave: [Cálem](https://tour.calem.pt/)","Francesinha: [Visit Portugal](https://www.visitportugal.com/en/destinos/porto-e-norte/73749) e [Câmara do Porto](https://www.porto.pt/pt/noticia/francesinha-no-top-europeu_2)","Trem: [CP Porto a Aveiro](https://www.cp.pt/info/documents/d/cp/comboios-urbanos-porto-aveiro)","Entrada: [Regulamento 2018/1806](https://home-affairs.ec.europa.eu/system/files/2020-05/regulation-2018-1806.pdf), [Your Europe](https://europa.eu/youreurope/citizens/travel/entry-exit/non-eu-nationals/index_en.htm), [EES](https://home-affairs.ec.europa.eu/policies/schengen/smart-borders/entry-exit-system_en) e [ETIAS](https://home-affairs.ec.europa.eu/policies/schengen/smart-borders/european-travel-information-authorisation-system_en)","Câmbio: [Banco Central, 11/11/2026](https://www4.bcb.gov.br/Download/fechamento/20261111.csv)"],"title":"Fontes oficiais, conferidas em 12/11/2026"},{"t":"tip","items":["Horário e preço oficiais do claustro da Sé (fontes divergem)","Preço, duração e horário da visita com prova na cave Cálem e em outras caves de Gaia","Preço do bilhete do elétrico e horário de inverno da linha 1 (STCP)","Se o Jardim do Morro terá obras ou vedação (só imprensa de agosto de 2026)","Tempo de trem, preço e horários Porto a Aveiro e a Braga (CP)","Preço de táxi do aeroporto (FAQ do Visit Porto defasado)","Valor dos meios de subsistência na entrada em Portugal","Data de início do ETIAS","Fechamento do Palácio da Bolsa e se o horário muda por estação","Taxa turística do Porto e preços de refeição: fora do guia","Horário de funcionamento da Lello (19h na aba Horário, 19h30 no cabeçalho)"],"title":"O que este guia não informa"},{"t":"p","text":"Preços, horários e regras mudam: confira nas fontes acima antes de ir. As estimativas de tempo e esforço e as dicas marcadas como da Rota Certa são recomendações nossas, não dados oficiais."},{"t":"p","text":"Foto de capa: Harry Shum / Pexels."},{"t":"whatsapp"},{"t":"p","text":"Quer montar o roteiro da viagem inteira? Use o [Planner grátis da Rota Certa](https://rotacertapassagens.com/#/planner)."},{"t":"contato"},{"t":"afiliado"}]', 10);
